protected void init()
{
    api = XAPI_APIS::CreateInstallation;
    super();
}

protected void postRun()
{
    EGS_API_DataContract_Response_Installation res;

    if (!responseText)
    {
        return;
    }

    res      = FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response_Installation), responseText);
    logKey   = "InstNum";
    logValue = res.parmInstallationNum();
}

protected str body()
{
    Map configMap = new Map(Types::String, Types::String);
    configMap.insert('<DataAreaId>', curExt());
    configMap.insert('<netArea>',    curExt());

    return this.prepareBody(configMap);
}
